// startupFailure is a password login that PostgreSQL ends after it is
// authenticated and authorized.
func startupFailure(session, code, message string) []string {
	head := `{"level":"info","ts":"2026-10-01T22:29:01.000000000Z","logger":"postgres","msg":"record","logging_pod":"cnpg-1","record":{"log_time":"2026-10-01 22:29:01.000 UTC","user_name":"included","database_name":"app","process_id":"1201","connection_from":"10.42.0.6:40002","session_id":"` + session + `",`
	return []string{
		head + `"session_line_num":"2","command_tag":"authentication","error_severity":"LOG","sql_state_code":"00000","message":"connection authenticated: identity=\"included\" method=scram-sha-256 (/var/lib/postgresql/data/pgdata/pg_hba.conf:26)","backend_type":"client backend","query_id":"0"}}`,
		head + `"session_line_num":"3","command_tag":"authentication","error_severity":"LOG","sql_state_code":"00000","message":"connection authorized: user=included database=app application_name=psql","backend_type":"client backend","query_id":"0"}}`,
		head + `"session_line_num":"4","command_tag":"startup","error_severity":"FATAL","sql_state_code":"` + code + `","message":"` + message + `","backend_type":"client backend","query_id":"0"}}`,
	}
}

